for target, replacement_text in FILES.items():
  subprocess.run(
    ["git", "checkout", "--", str(target).replace("\\\\", "/")],
    cwd=ROOT,
    check=True,
  )
  path = ROOT / target
  original = path.read_bytes()
  newline = b"\r\n" if b"\r\n" in original else b"\n"
  replacement = replacement_text.encode("utf-8").replace(b"\n", newline)
  path.write_bytes(replacement)
  print("Updated:", target)
  print("Preserved newline:", "CRLF" if newline == b"\r\n" else "LF")

